<script setup lang="ts">
import AssigneeFilter from './AssigneeFilter.vue'
import { bootstrap } from '../composables/api'
import { reactive, watch } from 'vue'
import { useRoute,useRouter } from 'vue-router'
defineProps<{environments?:string[];advanced?:boolean;allowedTags?:string[]}>()
const route=useRoute(),router=useRouter()
const draft=reactive<Record<string,string>>({})
watch(()=>route.query,()=>{for(const k of Object.keys(draft))delete draft[k];for(const[k,v]of Object.entries(route.query))if(typeof v==='string')draft[k]=v;draft.status??='unresolved';draft.sort??='last_seen';draft.per_page??='25'},{immediate:true})
function set(key:string,value:string){router.replace({query:{...route.query,[key]:value||undefined,page:undefined}})}
function search(){router.replace({query:{...draft,page:undefined}})}
</script>
<template><div v-if="!advanced" class="investigation-controls"><label><span class="sr-only">Environment</span><select aria-label="Environment" :value="route.query.environment??''" @change="set('environment',($event.target as HTMLSelectElement).value)"><option value="">All environments</option><option v-for="e in environments" :key="e">{{ e }}</option></select></label><label><span class="sr-only">Time range</span><select aria-label="Time range" :value="route.query.range??'24h'" @change="set('range',($event.target as HTMLSelectElement).value)"><option value="1h">Last hour</option><option value="24h">Last 24 hours</option><option value="7d">Last 7 days</option><option value="30d">Last 30 days</option></select></label><label class="test-toggle"><input type="checkbox" :checked="route.query.include_tests==='1'" @change="set('include_tests',($event.target as HTMLInputElement).checked?'1':'0')">Include test events</label></div><form v-if="advanced" class="inbox-filters" @submit.prevent="search"><label class="search-field"><span class="sr-only">Search exception class or message</span><input v-model="draft.search" aria-describedby="inbox-search-history" placeholder="Search exception class or message" type="search"></label><select v-model="draft.status" aria-label="Status"><option value="unresolved">Unresolved</option><option value="resolved">Resolved</option><option value="ignored">Ignored</option><option value="snoozed">Snoozed</option><option value="all">All statuses</option></select><select v-model="draft.sort" aria-label="Sort errors"><option value="last_seen">Last seen</option><option value="first_seen">First seen</option><option value="occurrences">Occurrences in range</option></select><button class="button" type="submit">Apply filters</button><p id="inbox-search-history" class="search-disclosure">Search terms appear in authenticated URLs and browser history.</p><details class="advanced-filters"><summary>More filters</summary><div class="filter-grid"><label class="field">Origin<select v-model="draft.origin"><option value="">Any origin</option><option v-for="o in ['web','job','command','unknown']" :key="o">{{o}}</option></select></label><AssigneeFilter v-if="bootstrap?.features.assignments" v-model="draft.assignee"/><label class="field">Exact exception class<input v-model="draft.class"></label><label v-if="allowedTags?.length" class="field">Permitted tag (key:value)<input v-model="draft.tag"><small>{{ allowedTags.join(', ') }}</small></label><label v-for="field in ['first_after','first_before','last_after','last_before']" :key="field" class="field">{{ field.replace('_',' seen ') }} (UTC)<input v-model="draft[field]" type="date"></label><label class="field">Rows per page<select v-model="draft.per_page"><option v-for="size in [25,50,100]" :key="size">{{size}}</option></select></label></div></details></form></template>
